import {
  Component,
  Element,
  Event,
  type EventEmitter,
  Host,
  Prop,
  State,
  Watch,
  h,
} from "@stencil/core";
import { addConstructedStyle } from "../../utils/browser";

/**
 * @since 2.8.0
 * @status experimental
 *
 * @slot - The text for truncation
 *
 * @part base - The base wrapper.
 */

@Component({
  tag: "hbr-truncate",
  styleUrl: "truncate.scss",
  shadow: true,
})
export class Truncate {
  slotRef: HTMLSlotElement;
  displayRef: HTMLDivElement;

  /** The ellipsis position. */
  @Prop({ reflect: true }) position: "start" | "end" | "middle" = "end";

  /** Allow limiting of the contents of a block to the specified number of lines.  */
  @Prop({ reflect: true, mutable: true }) lines = 1;

  /** The maximum number of characters to display before truncating. this overrides the display width if used with charWidth */
  @Prop({ reflect: true }) maxlength: number;

  /** The approximate width of a character in pixels, this is to calculating how many text in a line */
  @Prop({ reflect: true }) charWidth: number | "auto" = "auto";

  @Element() host: HTMLHbrOptionElement;

  @State() truncatedText: string;

  @State() truncated = false;

  /** Emitted when the truncation changes. */
  @Event({ eventName: "hbr-truncate-change" }) hbrTruncateChange: EventEmitter;

  @Watch("truncated")
  handleTruncatedChange() {
    this.hbrTruncateChange.emit({ truncated: this.truncated });
  }

  private container: HTMLDivElement;
  private sheet: CSSStyleSheet = new CSSStyleSheet();

  private getSlotTextWidth = () => {
    if (!this.slotRef) return 0;
    this.slotRef.style.display = "block";
    const node = this.slotRef.assignedNodes()[0] as HTMLElement;
    if (!node) return;

    const range = this.host.ownerDocument.createRange();
    range.selectNodeContents(node);
    const width = range.getBoundingClientRect().width;
    this.slotRef.style.removeProperty("display");
    return width;
  };

  private getNumOfCharAndCharWidth = (textWidth: number, hostWidth: number) => {
    // average width of a character, auto mode
    const charWidth =
      this.charWidth === "auto"
        ? textWidth / this.host.textContent.length
        : this.charWidth;
    const maxNumOfChar = Math.floor(hostWidth / charWidth) * this.lines;
    return {
      maxNumOfChar,
      charWidth,
    };
  };

  private handleResize = () => {
    const textWidth = this.getSlotTextWidth();

    const characterWidth =
      this.charWidth === "auto"
        ? textWidth / this.host.textContent.length
        : this.charWidth;

    this.displayRef?.style.setProperty("display", "none");

    const hostWidth = this.maxlength
      ? characterWidth * this.maxlength
      : this.host.getBoundingClientRect().width;

    // always set the width of the container to the host width
    // for dragging and resizing
    this.displayRef?.style.setProperty("display", "");
    this.displayRef?.style.setProperty("width", `${hostWidth}px`);

    // reset class
    if (this.displayRef) {
      this.displayRef.className = "";
    }

    // if host width is greater than the content width, then it is not truncated
    // this gets triggered when class is changed too
    // so a only check when it is not equal
    if (hostWidth > textWidth) {
      this.truncated = false;
      this.truncatedText = this.host.textContent || "";
    } else if (hostWidth < textWidth) {
      if (this.lines > 1) {
        this.displayRef?.classList.add("truncate--multiline");
        this.displayRef?.classList.add(`truncate--${this.position}`);
        this.displayRef?.classList.add(`truncate--lines-${this.lines}`);

        if (this.position === "start") {
          const cuttingText = this.host.textContent || "";

          const { maxNumOfChar } = this.getNumOfCharAndCharWidth(
            textWidth,
            hostWidth
          );
          // 3 is for stimulated ellipsis sizing
          this.truncatedText = `...${cuttingText.slice(-maxNumOfChar + 3)}`;
        } else {
          if (this.position === "middle") {
            console.warn(
              "Truncate: Middle position is not supported for multiline truncation."
            );
          }
          this.truncatedText = this.host.textContent || "";
        }
      } else {
        this.displayRef?.classList.add("truncate--single");
        this.displayRef?.classList.add(`truncate--${this.position}`);
        this.displayRef?.classList.add(`truncate--lines-${this.lines}`);

        if (this.position === "start" || this.position === "middle") {
          let cuttingText = this.host.textContent || "";

          const { maxNumOfChar } = this.getNumOfCharAndCharWidth(
            textWidth,
            hostWidth
          );
          if (textWidth > hostWidth) {
            if (this.position === "start") {
              // 3 is for stimulated ellipsis sizing
              cuttingText = `...${cuttingText.slice(-maxNumOfChar + 3)}`;
            } else if (this.position === "middle") {
              const half = Math.floor(maxNumOfChar / 2);
              // -1 and 2 is for stimulated ellipsis sizing
              cuttingText = `${cuttingText.slice(
                0,
                half - 1
              )}...${cuttingText.slice(-half + 2)}`;
            }
          }
          this.truncatedText = cuttingText;
        } else {
          this.truncatedText = this.host.textContent || "";
        }
      }
    }
    if (textWidth / this.lines > hostWidth) {
      this.truncated = true;
    } else {
      this.truncated = false;
    }
  };

  render() {
    const { lines, truncatedText } = this;

    if (this.host) {
      this.sheet.replaceSync(`
    		:host {
    		--line-clamp: ${lines};
    		}
    	`);
      addConstructedStyle(this.host.shadowRoot, this.sheet);
    }

    return (
      <Host data-truncated={this.truncated}>
        <div
          ref={(el) => {
            this.container = el;
          }}
          part="base"
          class={{
            truncate: true,
          }}
        >
          <slot
            ref={(el) => {
              this.slotRef = el as HTMLSlotElement;
            }}
          />
        </div>
        <div
          ref={(el) => {
            this.displayRef = el;
          }}
        >
          {truncatedText || ""}
        </div>
        <hbr-resize-observer
          onHbr-resize={this.handleResize}
          anchor={this.host.parentElement}
          subscriber={this.container}
        />
      </Host>
    );
  }
}
